<div class="section-heading"><div><div class="eyebrow">Conteúdo e aquisição</div><h1>Blog do ApPlanner</h1><p class="text-secondary mb-0">Publique conteúdos para atrair, orientar e converter novos clientes.</p></div><a class="btn btn-primary" href="/master/blog/novo">+ Novo artigo</a></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Artigo</th><th>Status</th><th>Publicação</th><th>Autor</th><th></th></tr></thead><tbody><?php foreach($posts as $p):?><tr><td><strong><?=htmlspecialchars($p['title'])?></strong><small class="d-block text-secondary">/blog/<?=htmlspecialchars($p['slug'])?> <?=$p['featured']?'· Destaque':''?></small></td><td><span class="badge text-bg-<?=$p['status']==='published'?'success':($p['status']==='draft'?'warning':'secondary')?>"><?=htmlspecialchars($p['status'])?></span></td><td><?=htmlspecialchars($p['published_at']?:'—')?></td><td><?=htmlspecialchars($p['author_name'])?></td><td><a class="btn btn-sm btn-light" href="/master/blog/<?=(int)$p['id']?>/editar">Editar</a></td></tr><?php endforeach;?><?php if(!$posts):?><tr><td colspan="5" class="empty-state">Nenhum artigo criado.</td></tr><?php endif;?></tbody></table></div></div>
